// Builds the OpenAI request that extracts and qualifies an inbound lead.
const lead = $input.first().json;
const MODEL = 'gpt-4.1-mini';

const system = `You are a sales assistant for an Amazon brand management agency.
Extract structured data from an inbound lead and qualify it.
Return ONLY a JSON object with exactly these keys:
- brand_category: string, the product category (e.g. "Kitchen", "Pet supplies"); "Unknown" if unclear
- main_need: one of "Full account management", "PPC/Advertising", "Listing optimization", "Product launch", "Wholesale/Distribution", "Other"
- lead_score: integer 1-10 (10 = established brand, real revenue, clear and urgent need; 1 = spam or no fit)
- score_reason: string, max 25 words
- summary: string, 1-2 sentences the sales team can read in 5 seconds`;

const user = [
  `Name: ${lead['Full Name']}`,
  `Email: ${lead['Work Email']}`,
  `Company / Brand: ${lead['Company / Brand']}`,
  `Amazon store or ASIN link: ${lead['Amazon Store or ASIN Link'] || 'not provided'}`,
  `Monthly Amazon revenue: ${lead['Monthly Amazon Revenue']}`,
  `Message: ${lead['What do you need help with?']}`,
].join('\n');

return [{
  json: {
    requestBody: {
      model: MODEL,
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}];

// Merges the form data with the AI result into one clean row for Google Sheets.
// If the AI response is missing or not valid JSON, the lead is still saved and flagged for manual review.
const form = $('New Lead Form').first().json;
const response = $input.first().json;

let ai = {};
let aiStatus = 'ok';
try {
  ai = JSON.parse(response.choices[0].message.content);
} catch (error) {
  aiStatus = 'needs_review: AI response could not be parsed';
}

const rawScore = Number(ai.lead_score);
const leadScore = Number.isFinite(rawScore) ? Math.min(10, Math.max(1, Math.round(rawScore))) : '';
if (aiStatus === 'ok' && leadScore === '') aiStatus = 'needs_review: missing lead score';

const now = new Date();
return [{
  json: {
    created_at: now.toISOString(),
    lead_id: `L-${now.getTime().toString(36).toUpperCase()}`,
    name: form['Full Name'],
    email: (form['Work Email'] || '').trim().toLowerCase(),
    company: form['Company / Brand'],
    amazon_store: form['Amazon Store or ASIN Link'] || '',
    monthly_revenue: form['Monthly Amazon Revenue'],
    source: form['How did you hear about us?'] || 'Unknown',
    message: form['What do you need help with?'],
    brand_category: ai.brand_category || '',
    main_need: ai.main_need || '',
    lead_score: leadScore,
    score_reason: ai.score_reason || '',
    summary: ai.summary || '',
    ai_status: aiStatus,
  },
}];

// Formats the Slack alert. Hot leads are highlighted so sales can respond first.
const lead = $('Parse & Score Lead').first().json;
const score = lead.lead_score;

const label = score === '' ? '⚠️ NEEDS REVIEW'
  : score >= 7 ? '🔥 HOT LEAD'
  : score >= 4 ? '🟡 Warm lead'
  : '🔵 Cold lead';

const lines = [
  `*${label}* — ${lead.company} (${score === '' ? '?' : score}/10)`,
  `*Contact:* ${lead.name} · ${lead.email}`,
  `*Revenue:* ${lead.monthly_revenue} · *Need:* ${lead.main_need || 'n/a'} · *Category:* ${lead.brand_category || 'n/a'}`,
  `*Summary:* ${lead.summary || lead.message}`,
];
if (lead.score_reason) lines.push(`_Why this score: ${lead.score_reason}_`);
if (lead.ai_status !== 'ok') lines.push(`⚠️ ${lead.ai_status}`);
lines.push(`Lead ID: ${lead.lead_id} · Source: ${lead.source}`);

return [{ json: { slackText: lines.join('\n') } }];
